INSERT INTO monitors VALUES('b42f08c7-15e7-4783-a903-525347a19d6b','dns-monitor','DNS Monitor','Resolves the A record of example.com through Cloudflare.',20,'c074f2be-b8e8-4576-b46d-26529d8ecd34','dns',43200,'active','{"hostname":"example.com","recordType":"A","dnsServer":"1.1.1.1","expectedRecordValues":[]}','2026-06-17 19:56:28','2026-06-17 19:56:28','ui');
INSERT INTO monitors VALUES('d1fb6c4a-0294-44d8-aa90-16682765160a','github-status','GitHub Status','Polls the GitHub status page API and expects the overall indicator to be "none". Goes down during GitHub incidents, which breaks our CI.',60,'121cbd3f-eedc-4cf6-baf5-57016a9ae2a8','http',604800,'active','{"method":"GET","url":"https://www.githubstatus.com/api/v2/status.json","headers":{},"body":"","saveResponseBody":true,"saveResponseHeaders":false,"expectedStatusCodes":[200],"expectedBodyRegex":"\"indicator\":\\s*\"none\"","expectedHeaders":{"Content-Type":"application/json; charset=utf-8"},"expectedResponseTimeMs":null}','2026-06-19 19:57:28','2026-06-19 19:57:28','ui');
INSERT INTO monitors VALUES('afe5861f-c181-4fd6-80e6-a67025187784','google-homepage','Google Homepage','Sanity check for outbound internet access. If this is down, everything else probably is too.',30,'a3af8470-dead-448d-8e7d-8122520c4b39','http',172800,'active','{"method":"GET","url":"https://www.google.com","headers":{},"body":"","saveResponseBody":false,"saveResponseHeaders":false,"expectedStatusCodes":[200],"expectedBodyRegex":"","expectedHeaders":{},"expectedResponseTimeMs":1500}','2026-06-21 19:58:28','2026-06-21 19:58:28','ui');
INSERT INTO monitors VALUES('3c89b364-4c54-43a5-b16e-99d2ad08f8d2','cloudflare-trace','Cloudflare Trace','Hits Cloudflare''s trace endpoint on 1.1.1.1 and checks the response contains the edge location line.',60,'a3af8470-dead-448d-8e7d-8122520c4b39','http',172800,'active','{"method":"GET","url":"https://1.1.1.1/cdn-cgi/trace","headers":{},"body":"","saveResponseBody":true,"saveResponseHeaders":false,"expectedStatusCodes":[200],"expectedBodyRegex":"(?m)^colo=[A-Z]{3}$","expectedHeaders":{},"expectedResponseTimeMs":null}','2026-06-21 19:59:28','2026-06-21 19:59:28','ui');
INSERT INTO monitors VALUES('f39f4616-02f6-4613-9620-d04612c136d3','httpbin-post-echo','httpbin POST Echo','Sends a JSON body to httpbin and checks it is echoed back. Exercises request headers and body.',120,'8fb51615-f0cc-4320-8760-e0f63fb201f7','http',172800,'active','{"method":"POST","url":"https://httpbin.org/post","headers":{"Content-Type":"application/json","X-Leszmonitor":"seed"},"body":"{\"hello\":\"world\"}","saveResponseBody":true,"saveResponseHeaders":true,"expectedStatusCodes":[200],"expectedBodyRegex":"\"hello\":\\s*\"world\"","expectedHeaders":{},"expectedResponseTimeMs":null}','2026-07-01 20:00:28','2026-07-01 20:00:28','ui');
INSERT INTO monitors VALUES('3dddcfb6-03b6-4e6b-93d0-cd18f82b1c9f','teapot','I''m a Teapot','httpbin returns 418 here, and that is exactly what we expect.',300,'8fb51615-f0cc-4320-8760-e0f63fb201f7','http',172800,'active','{"method":"GET","url":"https://httpbin.org/status/418","headers":{},"body":"","saveResponseBody":false,"saveResponseHeaders":false,"expectedStatusCodes":[418],"expectedBodyRegex":"","expectedHeaders":{},"expectedResponseTimeMs":null}','2026-07-02 20:01:28','2026-07-02 20:01:28','ui');
INSERT INTO monitors VALUES('83771846-c6b4-4d19-9993-36cacbfb40ab','always-503','Always 503','Expects 200 from an endpoint that always returns 503. Should always be down.',60,'121cbd3f-eedc-4cf6-baf5-57016a9ae2a8','http',43200,'active','{"method":"GET","url":"https://httpbin.org/status/503","headers":{},"body":"","saveResponseBody":false,"saveResponseHeaders":false,"expectedStatusCodes":[200],"expectedBodyRegex":"","expectedHeaders":{},"expectedResponseTimeMs":null}','2026-06-22 20:02:28','2026-06-22 20:02:28','ui');
INSERT INTO monitors VALUES('c380496b-09ff-4266-96f4-5dec98c55a6b','slow-endpoint','Slow Endpoint','httpbin delays the response by 3 seconds while the check allows 1 second, so it fails on response time.',120,'121cbd3f-eedc-4cf6-baf5-57016a9ae2a8','http',43200,'active','{"method":"GET","url":"https://httpbin.org/delay/3","headers":{},"body":"","saveResponseBody":false,"saveResponseHeaders":false,"expectedStatusCodes":[200],"expectedBodyRegex":"","expectedHeaders":{},"expectedResponseTimeMs":1000}','2026-06-22 20:03:28','2026-06-22 20:03:28','ui');
