PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
    id            TEXT PRIMARY KEY,
    username      TEXT UNIQUE NOT NULL CHECK (LENGTH(username) >= 2) CHECK (LENGTH(username) <= 50),
    role          TEXT        NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
    password_hash TEXT        NOT NULL,

    created_at    DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at    DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE monitors (
    id                       TEXT PRIMARY KEY,
    slug                     TEXT NOT NULL CHECK (LENGTH(slug) >= 2) CHECK (LENGTH(slug) <= 50),
    name                     TEXT NOT NULL CHECK (LENGTH(name) >= 2) CHECK (LENGTH(name) <= 100),
    description              TEXT NOT NULL CHECK (LENGTH(description) <= 1000),
    interval                 INT  NOT NULL CHECK (interval > 0),       -- in seconds
    owner_id                 TEXT NOT NULL,                            -- user who created the monitor
    kind                     TEXT NOT NULL,
    result_retention_seconds INT  NOT NULL CHECK (result_retention_seconds > 0),
    run_state                TEXT NOT NULL,
    config                   TEXT NOT NULL CHECK (JSON_VALID(config)), -- JSON string

    created_at               DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at               DATETIME DEFAULT CURRENT_TIMESTAMP,
    source                   TEXT NOT NULL DEFAULT 'ui',

    UNIQUE (slug)
);
CREATE TABLE monitor_results (
    id                    TEXT PRIMARY KEY,
    monitor_id            TEXT    NOT NULL,
    status                TEXT    NOT NULL,
    is_manually_triggered BOOLEAN NOT NULL,
    duration_ms           INTEGER,

    failures              TEXT CHECK (failures IS NULL OR JSON_VALID(failures)), -- JSON string

    details               TEXT    NOT NULL,

    created_at            DATETIME DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (monitor_id) REFERENCES monitors (id) ON DELETE CASCADE
);
CREATE TABLE audit_logs (
    id          TEXT PRIMARY KEY,
    username    TEXT,
    resource_id TEXT,
    action      TEXT    NOT NULL,
    is_success  BOOLEAN NOT NULL,
    summary     TEXT CHECK (summary IS NULL OR LENGTH(summary) <= 1000),
    before      TEXT CHECK (before IS NULL OR JSON_VALID(before)), -- JSON string
    after       TEXT CHECK (after IS NULL OR JSON_VALID(after)),   -- JSON string
    trace_id    TEXT,

    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE monitor_status_changes (
    id              TEXT PRIMARY KEY,
    monitor_id      TEXT NOT NULL,
    caused_by_id    TEXT, -- UUID of the monitor result that caused the status change, NULL if caused by app downtime
    previous_status TEXT NOT NULL,
    next_status     TEXT NOT NULL,

    created_at      DATETIME DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (monitor_id) REFERENCES monitors (id) ON DELETE CASCADE,
    FOREIGN KEY (caused_by_id) REFERENCES monitor_results (id) ON DELETE SET NULL
);
CREATE TABLE tags (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT,
    color_hex   TEXT NOT NULL,

    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE monitor_tags (
    monitor_id TEXT NOT NULL,
    tag_id     TEXT NOT NULL,

    PRIMARY KEY (monitor_id, tag_id),
    FOREIGN KEY (monitor_id) REFERENCES monitors (id) ON DELETE CASCADE,
    FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE CASCADE
);
CREATE TABLE heartbeat (
    id      INTEGER PRIMARY KEY CHECK (id = 1),
    beat_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE app_downtime_windows (
    id         TEXT PRIMARY KEY,
    started_at DATETIME NOT NULL,
    ended_at   DATETIME NOT NULL
);
CREATE TABLE global_parameters (
    key        TEXT PRIMARY KEY,
    value      TEXT     NOT NULL,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER update_users_updated_at
    AFTER UPDATE
    ON users
    FOR EACH ROW
BEGIN
    UPDATE users SET updated_at = CURRENT_TIMESTAMP WHERE id = new.id;
END;
CREATE TRIGGER update_monitors_updated_at
    AFTER UPDATE
    ON monitors
    FOR EACH ROW
BEGIN
    UPDATE monitors SET updated_at = CURRENT_TIMESTAMP WHERE id = new.id;
END;
CREATE TRIGGER update_tags_updated_at
    AFTER UPDATE
    ON tags
    FOR EACH ROW
BEGIN
    UPDATE tags SET updated_at = CURRENT_TIMESTAMP WHERE id = new.id;
END;
CREATE TRIGGER update_global_parameters_updated_at
    AFTER UPDATE
    ON global_parameters
    FOR EACH ROW
BEGIN
    UPDATE global_parameters SET updated_at = CURRENT_TIMESTAMP WHERE key = new.key;
END;
CREATE INDEX idx_monitor_results_monitor_id_created ON monitor_results (monitor_id, created_at DESC);
CREATE INDEX idx_monitor_tags_tag_id ON monitor_tags (tag_id);
CREATE INDEX idx_app_downtime_windows_started_ended ON app_downtime_windows (started_at, ended_at);
COMMIT;
